import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`website-builder`,heroTitle:`Describe your site. Get it live.`,heroSubtitle:`Perplexity Computer designs, builds, and deploys your website — from a simple landing page to a full multi-page site, no coding required.`,inputUrlCta:`Build my site`,inputUrlPlaceholder:`Describe your website...`,inputUrlPrefill:`Build me a website: {url}. Research the best design patterns, layout structure, and copy approaches for this type of site. Design a modern, responsive UI with a strong hero section, clear navigation bar with logo and links, social proof or testimonials section, feature or benefit highlights with icons, and a compelling footer with contact info and links. Write all the page copy — headlines, subheadlines, body text, button labels, and calls to action — optimized for conversion. Build it fully responsive across desktop, tablet, and mobile breakpoints. Add SEO meta tags (title, description, keywords), Open Graph and Twitter Card images for social sharing, structured data markup, a sitemap, and robots.txt. Include a contact form with email delivery, an email capture popup or inline signup, and Google Analytics tracking code. Optimize for performance — lazy-loaded images, minified assets, and sub-2-second load time. Deploy it to a live URL. Before you start building, ask me any clarifying questions about brand style, color preferences, pages needed, or specific functionality.`,heroOverlaySteps:[`Researching the best design patterns and layout for your site`,`Designing the UI, writing copy, and building every page`,`Adding mobile responsiveness, SEO, and contact forms`,`Deployed to a live URL, ready to share`],generatingSteps:[`Analyzing your site idea to plan pages, layout, and design direction`,`Designing an agent to build the UI, write copy, and handle responsive design`,`Finding the best patterns for SEO, meta tags, and page speed`,`Setting up deployment to a live URL with custom domain support`],featureSectionTitle:`Describe it. Launch it.`,featureCardTitles:[`The best model for every task`,`Connects to your tools`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Analytics, Search Console, Notion — Computer sets up tracking and integrations so your site is ready from day one.`,`Responsive design. Fast load times. SEO-ready. Computer delivers a polished website deployed to a live URL — just share the link.`],capabilitySectionTitle:`Your web team, on demand`,capabilitySectionSubtitle:`Describe what you want, come back to a live website.`,capabilityCards:[{title:`Research & Plan`,description:`Computer researches the best design patterns, layouts, and copy approaches for your type of site before building anything.`},{title:`Design & Build`,description:`Computer designs a modern, responsive site with clean navigation, strong visuals, and compelling copy — from hero to footer.`},{title:`SEO & Performance`,description:`Computer adds meta tags, Open Graph images, fast load times, and mobile responsiveness — so your site ranks and loads fast.`},{title:`Preview & Iterate`,description:`Computer deploys a live preview so you can see your site, give feedback, and iterate — all in natural language.`},{title:`Knows Your Brand`,description:`Computer remembers your brand, style preferences, and past sites so every build starts with your guidelines already loaded.`},{title:`Forms & Integrations`,description:`Computer adds contact forms, email capture, analytics, and third-party integrations — so your site works from launch.`}]});export{t as default};
